//go:build cgo || integration

package db_test

import (
	"context"
	"errors"
	"fmt"
	"strconv"
	"testing"
	"time"

	"github.com/zhuhanxin0308/thinkgo/v3/db"
)

// table is generated by the test harness, never accepted from a request.
// This suite asserts actual row identities and persisted contents, not SQL strings alone.
func exerciseRawSQLBoundary(t *testing.T, database *db.DB, table string) {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	if _, err := database.ExecuteContext(ctx, "CREATE TABLE "+table+" (id INTEGER PRIMARY KEY, tenant_id INTEGER NOT NULL, name TEXT NOT NULL, note TEXT NOT NULL)"); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		cleanup, stop := context.WithTimeout(context.Background(), 10*time.Second)
		defer stop()
		if _, err := database.ExecuteContext(cleanup, "DROP TABLE "+table); err != nil {
			t.Error(err)
		}
	})
	inputs := []string{"x' OR 1=1 --", "x'; DELETE FROM " + table + "; --", "? :1 $1 @p1 /* ? */", "load_file('x'); sleep(1)", "资料 O'Reilly\\end", "100%_literal"}
	for index, input := range inputs {
		for _, tenant := range []int64{7, 8} {
			id := int64(index*10) + tenant
			if _, err := database.ExecuteContext(ctx, "INSERT INTO "+table+" (id, tenant_id, name, note) VALUES (?, ?, ?, ?)", id, tenant, input, "original"); err != nil {
				t.Fatal(err)
			}
		}
	}
	selectSQL := "SELECT id FROM " + table + " WHERE tenant_id = ? AND name = ?"
	updateSQL := "UPDATE " + table + " SET note = ? WHERE tenant_id = ? AND name = ?"
	for index, input := range inputs {
		t.Run(fmt.Sprint(index), func(t *testing.T) {
			expectedID := int64(index*10 + 7)
			rows, err := database.QueryContext(ctx, selectSQL, int64(7), input)
			assertRawBoundaryID(t, rows, err, expectedID)
			rows, err = database.Query(selectSQL, int64(7), input)
			assertRawBoundaryID(t, rows, err, expectedID)
			rows, err = database.Table(table).WithContext(ctx).Field("id").
				WhereField("tenant_id", "=", int64(7)).WhereRaw("name = ?", input).Select()
			assertRawBoundaryID(t, rows, err, expectedID)
			rows, err = database.Table(table).WithContext(ctx).Field("id").
				WhereField("tenant_id", "=", int64(7)).Group("id, name").
				HavingRaw("name = ? AND COUNT(*) = ?", input, int64(1)).Select()
			assertRawBoundaryID(t, rows, err, expectedID)
			// Editing an inspection result must not retarget the reusable query.
			tenant := int64(7)
			reusable := database.Table(table).WithContext(ctx).Field("id").
				WhereRaw("tenant_id = ? AND name = ?", &tenant, input).Group("id")
			_, inspected, err := reusable.BuildSelectSQL()
			if err != nil {
				t.Fatal(err)
			}
			copiedTenant, ok := inspected[0].(*int64)
			if !ok {
				t.Fatalf("unexpected argument type: %T", inspected[0])
			}
			*copiedTenant = 8
			rows, err = reusable.Select()
			assertRawBoundaryID(t, rows, err, expectedID)
			note := "saved:" + input
			if affected, err := database.ExecuteContext(ctx, updateSQL, note, int64(7), input); err != nil || affected != 1 {
				t.Fatalf("context update affected %d rows: %v", affected, err)
			}
			note = "saved-again:" + input
			if affected, err := database.Execute(updateSQL, note, int64(7), input); err != nil || affected != 1 {
				t.Fatalf("plain update affected %d rows: %v", affected, err)
			}
			rollback := errors.New("intentional rollback")
			err = database.TransactionContext(ctx, func(tx *db.Tx) error {
				found, err := tx.QueryContext(ctx, selectSQL, int64(7), input)
				if err != nil {
					return err
				}
				if err := rawBoundaryIDError(found, expectedID); err != nil {
					return err
				}
				affected, err := tx.ExecuteContext(ctx, updateSQL, "rolled-back:"+input, int64(7), input)
				if err != nil {
					return err
				}
				if affected != 1 {
					return fmt.Errorf("transaction changed %d rows", affected)
				}
				found, err = tx.Table(table).WithContext(ctx).Field("id").WhereRaw("tenant_id = ? AND name = ?", int64(7), input).Select()
				if err != nil {
					return err
				}
				if err := rawBoundaryIDError(found, expectedID); err != nil {
					return err
				}
				return rollback
			})
			if !errors.Is(err, rollback) {
				t.Fatalf("rollback result: %v", err)
			}
			if _, err := database.ExecuteContext(ctx, updateSQL, "invalid", int64(7)); !errors.Is(err, db.ErrInvalidQuery) {
				t.Fatalf("invalid binding not rejected: %v", err)
			}
			cancelled, stop := context.WithCancel(ctx)
			stop()
			if _, err := database.ExecuteContext(cancelled, updateSQL, "cancelled", int64(7), input); !errors.Is(err, context.Canceled) {
				t.Fatalf("cancelled execution: %v", err)
			}
			if _, err := database.QueryContext(cancelled, selectSQL, int64(7), input); !errors.Is(err, context.Canceled) {
				t.Fatalf("cancelled query: %v", err)
			}
			// A second, fixed-ID query checks both the committed value and the other tenant.
			for tenant, want := range map[int64]string{7: note, 8: "original"} {
				rows, err := database.QueryContext(ctx, "SELECT note FROM "+table+" WHERE id = ?", int64(index*10)+tenant)
				if err != nil || len(rows) != 1 || rawBoundaryText(rows[0]["note"]) != want {
					t.Fatalf("persisted state changed outside authorized update: tenant=%d rows=%#v err=%v", tenant, rows, err)
				}
			}
		})
	}
	rows, err := database.QueryContext(ctx, "SELECT id FROM "+table)
	if err != nil || len(rows) != 2*len(inputs) {
		t.Fatalf("table or row count changed: %d %v", len(rows), err)
	}
}

func rawBoundaryText(value interface{}) string {
	if data, ok := value.([]byte); ok {
		return string(data)
	}
	return fmt.Sprint(value)
}

func rawBoundaryIDError(rows []map[string]interface{}, want int64) error {
	if len(rows) != 1 {
		return fmt.Errorf("expected one row for %d, got %#v", want, rows)
	}
	got, err := strconv.ParseInt(rawBoundaryText(rows[0]["id"]), 10, 64)
	if err != nil || got != want {
		return fmt.Errorf("row identity: got %#v, want %d", rows, want)
	}
	return nil
}

func assertRawBoundaryID(t *testing.T, rows []map[string]interface{}, err error, want int64) {
	t.Helper()
	if err != nil {
		t.Fatal(err)
	}
	if err := rawBoundaryIDError(rows, want); err != nil {
		t.Fatal(err)
	}
}
